import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import { CustomerProvider, useCustomer } from '../context/CustomerContext';
import CustomerAuth from './CustomerAuth';
import CustomerHome from './CustomerHome';
import RestaurantDetails from './RestaurantDetails';
import CustomerCart from './CustomerCart';
import CustomerOrders from './CustomerOrders';
import CustomerProfile from './CustomerProfile';
import {
  Home,
  ShoppingBag,
  PackageCheck,
  User,
  MessageCircle
} from 'lucide-react';

function CustomerAppContent() {
  const { customer, cart } = useCustomer();
  const [activeTab, setActiveTab] = useState('home'); // home, cart, orders, profile
  const [activeRestaurant, setActiveRestaurant] = useState(null);
  const [supportPhone, setSupportPhone] = useState('01XXXXXXXXX');

  useEffect(() => {
    API.get('/settings').then((res) => {
      if (res.data?.support_number) setSupportPhone(res.data.support_number);
    });
  }, []);

  if (!customer) {
    return <CustomerAuth onAuthSuccess={() => setActiveTab('home')} />;
  }

  const cartCount = cart.reduce((sum, item) => sum + item.qty, 0);

  return (
    <div className="min-h-screen bg-slate-50 text-gray-900 font-sans relative">
      {/* Dynamic Content Views */}
      {activeRestaurant ? (
        <RestaurantDetails
          restaurant={activeRestaurant}
          onBack={() => setActiveRestaurant(null)}
          onGoCart={() => { setActiveRestaurant(null); setActiveTab('cart'); }}
        />
      ) : activeTab === 'home' ? (
        <CustomerHome onSelectRestaurant={(res) => setActiveRestaurant(res)} />
      ) : activeTab === 'cart' ? (
        <CustomerCart
          onOrderSuccess={() => setActiveTab('orders')}
          onGoHome={() => setActiveTab('home')}
        />
      ) : activeTab === 'orders' ? (
        <CustomerOrders />
      ) : (
        <CustomerProfile onLogout={() => setActiveTab('home')} />
      )}

      {/* Floating WhatsApp Support Button */}
      <a
        href={`https://wa.me/88${supportPhone}`}
        target="_blank"
        rel="noreferrer"
        className="fixed bottom-20 right-4 z-40 w-12 h-12 bg-emerald-500 hover:bg-emerald-600 text-white rounded-full flex items-center justify-center shadow-xl shadow-emerald-500/40 transition-transform active:scale-95 cursor-pointer"
        title="Chat with WhatsApp Support"
      >
        <MessageCircle className="w-6 h-6" />
      </a>

      {/* Fixed 4 Bottom Navigation Bar */}
      <div className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-200 py-2.5 px-6 z-50">
        <div className="max-w-md mx-auto flex justify-between items-center">
          <button
            onClick={() => { setActiveRestaurant(null); setActiveTab('home'); }}
            className={`flex flex-col items-center gap-1 cursor-pointer transition-colors ${
              activeTab === 'home' && !activeRestaurant ? 'text-emerald-600 font-bold' : 'text-gray-400'
            }`}
          >
            <Home className="w-5 h-5" />
            <span className="text-[10px]">Home</span>
          </button>

          <button
            onClick={() => { setActiveRestaurant(null); setActiveTab('cart'); }}
            className={`flex flex-col items-center gap-1 relative cursor-pointer transition-colors ${
              activeTab === 'cart' ? 'text-emerald-600 font-bold' : 'text-gray-400'
            }`}
          >
            <ShoppingBag className="w-5 h-5" />
            <span className="text-[10px]">Cart</span>
            {cartCount > 0 && (
              <span className="absolute -top-1 -right-2 bg-emerald-600 text-white text-[9px] font-black rounded-full w-4 h-4 flex items-center justify-center">
                {cartCount}
              </span>
            )}
          </button>

          <button
            onClick={() => { setActiveRestaurant(null); setActiveTab('orders'); }}
            className={`flex flex-col items-center gap-1 cursor-pointer transition-colors ${
              activeTab === 'orders' ? 'text-emerald-600 font-bold' : 'text-gray-400'
            }`}
          >
            <PackageCheck className="w-5 h-5" />
            <span className="text-[10px]">Orders</span>
          </button>

          <button
            onClick={() => { setActiveRestaurant(null); setActiveTab('profile'); }}
            className={`flex flex-col items-center gap-1 cursor-pointer transition-colors ${
              activeTab === 'profile' ? 'text-emerald-600 font-bold' : 'text-gray-400'
            }`}
          >
            <User className="w-5 h-5" />
            <span className="text-[10px]">Profile</span>
          </button>
        </div>
      </div>
    </div>
  );
}

export default function CustomerApp() {
  return (
    <CustomerProvider>
      <CustomerAppContent />
    </CustomerProvider>
  );
}
